custom_settings.custom_style:
@media (min-width: 1160px) {
.layout-1220 .block.category.event, .layout-1220 .footer.content, .layout-1220 .header.content, .layout-1220 .page-main, .layout-1220 .page-wrapper>.breadcrumbs >ul, .layout-1220 .page-wrapper>.page-bottom, .layout-1220 .page-wrapper>.widget, .layout-1220 .top-container, .layout-1220 .container, .container,.page-header.type15 .header-main .header.content,.layout-1220 .navigation {
  max-width: 1140px;
}
}
@media (min-width: 1480px) {
.layout-1220 .block.category.event, .layout-1220 .footer.content, .layout-1220 .header.content, .layout-1220 .page-main, .layout-1220 .page-wrapper>.breadcrumbs >ul, .layout-1220 .page-wrapper>.page-bottom, .layout-1220 .page-wrapper>.widget, .layout-1220 .top-container, .layout-1220 .container, .container,.page-header.type15 .header-main .header.content,.layout-1220 .navigation {
  max-width: 1440px;
}
}
:root{
--light-color: #FFF;
}
@media (max-width: 575px){
  body {
    font-size: 13px;
    line-height: 21px;
  }
}
p {
  margin: 0 0 1.25rem;
  line-height: 24px;
  letter-spacing: normal;
}
h1, h2, h3, h4, h5, h6 {
  color: #222529;
  letter-spacing: normal;
  font-family: Lexend;
}
h1 {
  font-weight: 400;
  font-size: 36px;
  line-height: 44px;
  margin: 0 0 32px 0;
}
h2 {
  font-weight: 400;
  font-size: 30px;
  line-height: 40px;
  margin: 0 0 32px 0;
}
h3 {
  font-weight: 400;
  font-size: 25px;
  line-height: 32px;
  margin: 0 0 20px 0;
}
h4 {
  font-weight: 400;
  font-size: 20px;
  line-height: 27px;
  margin: 0 0 14px 0;
}
h5 {
  font-weight: 400;
  font-size: 14px;
  line-height: 18px;
  margin: 0 0 14px 0;
}
h6 {
  font-weight: 400;
  font-size: 14px;
  line-height: 18px;
  margin: 0 0 14px 0;
}
.ms-auto {
    margin-left: auto !important;
}
.home-banner-slider h2.vc_custom_heading, .custom-font4 {
  font-family: 'Segoe Script','Savoye LET';
}
html .heading-secondary, html .lnk-secondary, html .text-color-secondary {
  color: #ed7e63;
}
html .btn-modern {
  text-transform: uppercase;
  font-size: .75rem;
  padding: .75rem 1.5rem;
  font-weight: 600;
  height: auto;
}
html .action.primary, html .btn {
  font-family: Poppins;
  letter-spacing: 0;
  font-weight: 600;
  padding: .533rem .933rem;
  font-size: 1em;
  line-height: 1.42857;
  border-radius: 2em;
    background-color: var(--button-bg-color);
    border-color: var(--button-border-color);
    color: var(--button-text-color);
}
html .btn-modern {
  font-size: .8125rem;
  padding: 1em 2.8em;
}
html .btn-xs {
  padding: .2rem .5rem;
  font-size: .7rem;
  line-height: 1.5;
}
html .btn-xl {
  font-size: 1rem;
  padding: .8rem 2rem;
}
.btn-modern.btn-xl {
  font-size: 1rem;
  padding: 1.25em 3.125em;
}
html .btn-lg {
  font-size: .875rem;
  line-height: 1.3333;
}
.btn-default.btn {
  border-color: #e7e7e7;
  border-width: 2px;
  border-style: solid;
}
.btn-default.btn:hover {
    background-color: #f2f2f2;
    border-color: rgba(0,0,0,.06);
}
.btn.btn-borders {
  padding: .8em 1.4em;
  font-weight: 700;
  letter-spacing: .15em;
  background: transparent;
}
.btn-borders.btn-lg {
  padding: 1em 1.6em;
}
html .btn-borders.btn-light {
  background: transparent;
  border-color: #fff;
  color: #fff;
}
.btn-flat {
  padding: 0!important;
  background: none!important;
  border: none!important;
  border-bottom: 1px solid transparent!important;
  box-shadow: none!important;
  text-transform: uppercase;
  font-size: .75rem;
}
html .btn-dark {
  color: #fff;
  background-color: #222529;
  border-color: #222529 #222529 #0b0c0e;
}
html .btn-light {
  color: #222529;
  background-color: #fff;
  border-color: #fff #fff #e6e6e6;
}
html .btn-quaternary {
  color: #fff;
  background-color: #000;
  border-color: #000 #000 #000;
}
html .background-color-secondary {
  background-color: #f4a085 !important;
}
.porto-icon-shopping-cart:before {
    content: '\e829';
}
.top-icon .porto-sicon-header {
  margin-bottom: .75rem;
}

@media (min-width: 768px) {
    .me-md-3 {
        margin-right: 1rem !important;
    }
}
.product-type-advanced > .porto-tb-featured-image.product-image {
    border: 1px solid #e7e7e7;
    border-radius: 0.7rem 0.7rem 0.7rem 0.7rem;
}
.page-layout-1column .toolbar-products {
    justify-content: flex-end;
}
.porto-cp-attr-table tbody {
    display: grid;
    grid-template-columns: repeat(var(--porto-sp-table-cols), 1fr);
    padding-top: 12px;
    margin-bottom: calc(-1* 13px);
}
.post-list .post-image .image-wrap {
    border-radius: 10px;
}
table.porto-cp-attr-table.wc-attr-table th {
    padding: 0;
}
.product.attribute.description .porto-attr-title {
    font-weight: 600;
    letter-spacing: 0.1em;
    font-size: 13px;
    background-color: #f7f7f7;
    line-height: 1.615;
    padding: 10px 20px;
    text-transform: uppercase;
    display: block;
    color: #222529;
}
.porto-cp-attr-table .porto-attr-data {
    display: flex;
    justify-content: space-between;
    align-items: center;
    letter-spacing: 0.01em;
    padding-left: 20px;
    padding-right: 20px;
    padding-bottom: 15px;
    margin-bottom: 15px;
    border-bottom: 1px solid #eeeeee;
    line-height: 21px;
}
.porto-cp-attr-table .porto-attr-data .porto-attr-name {
    font-weight: 500;
    margin-right: 10px;
}
.porto-cp-attr-table .porto-attr-data .porto-attr-term {
    font-weight: 600;
    color: #222529;
    text-align: end;
}
.porto-cp-attr-table .porto-attr-data th, .porto-cp-attr-table .porto-attr-data td {
    padding: 0;
}
.fotorama__stage {
    border: 2px solid #f4f4f4;
    border-radius: 10px;
    margin-bottom: 8px;
}
.fotorama__thumb,.fotorama__thumb {
    border-radius: 10px;
}
.fotorama__nav .fotorama__thumb-border {
    border-radius: 10px;
}
.product-info-detailed .product-data-items .data-item-title h2 {
    font-size: 1.5rem;
    font-weight: 700;
    margin-bottom: 0.8rem;
}
.product-info-detailed .product-data-items .data-item-title h2 span.counter:after {
    content: ")";
}
.product-info-detailed .product-data-items .data-item-title h2 span.counter:before {
    content: "(";
}
.product-info-detailed .data-item-content {
    margin-bottom: 1.9rem;
    padding: 0;
    font-size: 1rem;
}
.product-info-detailed .data-item-content:not(:last-child) {
    border-bottom: 2px solid #e7e7e7;
    padding-bottom: 30px;
}
li.item.review-item {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
}
.review-form .action.submit.primary {
    margin: 0;
    font-weight: 600;
    text-transform: uppercase;
    padding: 0 3rem;
    border-radius: 1.5rem;
    background-color: #222529;
    border-color: #222529;
}
div#product-review-container {
    display: inline-block;
    width: calc(52% - 25px);
    margin-right: 20px;
}
.block.review-add {
    display: inline-block;
    vertical-align: top;
    width: 48%;
}
.review-add .review-form {
	max-width: 100%;
}
.review-list li.item.review-item {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
}
.porto-info-list li, .product.description ul li {
    list-style: disc;
    padding-top: 0;
    padding-bottom: 0;
    margin: 0;
    display: list-item;
    letter-spacing: -0.015em;
}
@media(max-width: 767px){
div#product-review-container {
    width: 100%;
    margin-right: 0;
}
.block.review-add {
    width: 100%;
}
}
  .owl-carousel .owl-dots .owl-dot span,.owl-carousel .owl-dots .owl-dot.active span, .owl-carousel .owl-dots .owl-dot:hover span {
    background: #222529;
  }
.catalog-category-view .sidebar.sidebar-main .sidebar-content, .catalogsearch-result-index .sidebar.sidebar-main .sidebar-content {
    border: none;
}
.sidebar .sidebar-content .block-category-list, .side-custom-block .custom-block, .sidebar .sidebar-content .side-megamenu, .block.filter > .content {
    padding: 20px 0;
}
.filter-current, .filter-actions {
    padding-left: 0;
    padding-right: 0;
}
.filter-options-item {
    padding: 20px 0;
}
.filter-options-title,.block-category-list .block-title, .side-custom-block .custom-block h2, .filter .filter-current-subtitle{
    line-height: 2em;
    text-transform: capitalize;
}
.page-wrapper .breadcrumbs {
    font-weight: 600;
}
.slider-title, .section-title {
  letter-spacing: .15em;
}
.widget .widgettitle {
  font-size: 1rem;
  letter-spacing: -.02em;
}
.footer, .footer p {
    font-size: 14px;
    line-height: 24px;
    font-weight: 500;
    letter-spacing: 0.005em;
}
.footer li {
    margin-bottom: 0.5rem;
}
.footer-middle > .container {
    padding-top: 4.2rem;
    padding-bottom: 2.1rem;
}
.footer .widgettitle, .footer .widget-title, .footer .porto-u-sub-heading {
    text-transform: capitalize;
    font-size: 1.125rem;
    line-height: normal;
    font-weight: 600;
    letter-spacing: 0;
    margin-bottom: 20px;
}
.footer-top .custom-block {
  display: block;
}
.footer-top .custom-block:before, .footer-top .custom-block::after {
  display: none;
}
.footer .widget + .widget {
  margin-top: 0;
}
.footer-middle > .container::after {
  display: none;
}
.footer .follow-us .share-links a {
  width: 38px;
  height: 38px;
  border: none;
  font-size: 0.8rem;
  margin-right: 10px;
}
.footer .follow-us .share-links a:not(:hover) {
    color: #222529;
    background-color: #fff;
    border: none;
}
.footer-bottom {
    padding: 1.3375rem 0;
    padding-bottom: 1.3375rem;
}
.footer-bottom .widget_text.widget.widget_custom_html {
    margin-bottom: 0;
}
.footer-middle [class^="porto-icon-"], .footer-middle [class*=" porto-icon-"] {
    color: inherit;
}
.footer-bottom address {
    font-size: 14px;
    color: #777777;
    line-height: 36px;
    font-weight: 500;
    letter-spacing: -0.1px;
}
@media (min-width: 1480px) {
    .col-xxl-3 {
        max-width: 25%;
        flex: 0 0 25%;
    }
}
